535     assign unused_fetch_enable = ^fetch_enable_i[$bits(ibex_mubi_t)-1:1];
536 
537     assign instr_req_gated = instr_req_int & fetch_enable_i[0];
538     assign instr_exec      = fetch_enable_i[0];
