1395     // instruction leaves WB
1396     assign rvfi_stage_valid_d[0] = (rvfi_id_done & ~dummy_instr_id) |
1397                                    (rvfi_stage_valid[0] & ~rvfi_wb_done);
1398     // Second stage is output stage so simple valid cycle after instruction leaves WB (and so has
1399     // retired)
1400     assign rvfi_stage_valid_d[1] = rvfi_wb_done;
