1460   assign new_debug_req = (debug_req_i & ~debug_mode);
1461   assign new_nmi = irq_nm_i & ~nmi_mode & ~debug_mode;
1462   assign new_nmi_int = id_stage_i.controller_i.irq_nm_int & ~nmi_mode & ~debug_mode;
1463   assign new_irq = irq_pending_o & (csr_mstatus_mie || (priv_mode_id == PRIV_LVL_U)) & ~nmi_mode &
