1472       captured_debug_req <= 1'b0;
1473       rvfi_irq_valid     <= 1'b0;
1474     end else  begin
1475       // Capture when ID stage has emptied out and something occurs that will cause a trap and we
1476       // haven't yet captured
1477       //
