1857       rvfi_intr_q        <= 1'b0;
1858     end else begin
1859       rvfi_set_trap_pc_q <= rvfi_set_trap_pc_d;
1860       rvfi_intr_q        <= rvfi_intr_d;
1861     end
1862   end
